import importlib.resources as _ir
resource_filename = lambda pkg, path: str(_ir.files(pkg).joinpath(path))

from mudlab.generic.views import DialogView


class TrimView(DialogView):
    title = "Trim specimen"
    subview_builder = resource_filename(__name__, "../glade/trim_dialog.glade")
    subview_toplevel = "tbl_trim"
    modal = True
    resizable = False

    def __init__(self, *args, **kwargs):
        super(TrimView, self).__init__(*args, **kwargs)
        self.get_toplevel().set_default_size(-1, -1)
